INSERT INTO `_import_descripciones_seo_novatec`
(`slug`, `descripcion`, `breve_descripcion`)
VALUES
('terma-solar-de-08-tubos-al-vacio', '<h3>Características del producto</h3><p>La Terma solar de 08 tubos al vacío aprovecha la energía solar para el calentamiento de agua.</p><p>Es una opción recomendada para viviendas pequeñas, puntos de consumo moderado y usuarios que buscan reducir el uso de electricidad o gas para calentar agua.</p><ul><li>Tipo: terma solar</li><li>Tecnología: tubos al vacío</li><li>Cantidad de tubos: 08</li><li>Aplicación: agua caliente sanitaria con energía solar</li></ul><p>Novatec Energy brinda asesoría para elegir la capacidad adecuada según cantidad de usuarios, consumo diario y condiciones de instalación.</p>', 'Terma solar de 08 tubos al vacío para calentamiento de agua con energía solar, recomendado para viviendas pequeñas, puntos de consumo moderado y usuarios que buscan reducir el uso de electricidad o gas para calentar agua.'),
('terma-solar-de-10-tubos-al-vacio', '<h3>Características del producto</h3><p>La Terma solar de 10 tubos al vacío aprovecha la energía solar para el calentamiento de agua.</p><p>Es una opción recomendada para viviendas pequeñas, puntos de consumo moderado y usuarios que buscan reducir el uso de electricidad o gas para calentar agua.</p><ul><li>Tipo: terma solar</li><li>Tecnología: tubos al vacío</li><li>Cantidad de tubos: 10</li><li>Aplicación: agua caliente sanitaria con energía solar</li></ul><p>Novatec Energy brinda asesoría para elegir la capacidad adecuada según cantidad de usuarios, consumo diario y condiciones de instalación.</p>', 'Terma solar de 10 tubos al vacío para calentamiento de agua con energía solar, recomendado para viviendas pequeñas, puntos de consumo moderado y usuarios que buscan reducir el uso de electricidad o gas para calentar agua.'),
('terma-solar-de-12-tubos-al-vacio', '<h3>Características del producto</h3><p>La Terma solar de 12 tubos al vacío aprovecha la energía solar para el calentamiento de agua.</p><p>Es una opción recomendada para viviendas pequeñas, puntos de consumo moderado y usuarios que buscan reducir el uso de electricidad o gas para calentar agua.</p><ul><li>Tipo: terma solar</li><li>Tecnología: tubos al vacío</li><li>Cantidad de tubos: 12</li><li>Aplicación: agua caliente sanitaria con energía solar</li></ul><p>Novatec Energy brinda asesoría para elegir la capacidad adecuada según cantidad de usuarios, consumo diario y condiciones de instalación.</p>', 'Terma solar de 12 tubos al vacío para calentamiento de agua con energía solar, recomendado para viviendas pequeñas, puntos de consumo moderado y usuarios que buscan reducir el uso de electricidad o gas para calentar agua.'),
('terma-solar-de-15-tubos-al-vacio', '<h3>Características del producto</h3><p>La Terma solar de 15 tubos al vacío aprovecha la energía solar para el calentamiento de agua.</p><p>Es una opción recomendada para viviendas familiares, negocios pequeños y espacios con consumo medio de agua caliente.</p><ul><li>Tipo: terma solar</li><li>Tecnología: tubos al vacío</li><li>Cantidad de tubos: 15</li><li>Aplicación: agua caliente sanitaria con energía solar</li></ul><p>Novatec Energy brinda asesoría para elegir la capacidad adecuada según cantidad de usuarios, consumo diario y condiciones de instalación.</p>', 'Terma solar de 15 tubos al vacío para calentamiento de agua con energía solar, recomendado para viviendas familiares, negocios pequeños y espacios con consumo medio de agua caliente.'),
('terma-solar-de-18-tubos-al-vacio', '<h3>Características del producto</h3><p>La Terma solar de 18 tubos al vacío aprovecha la energía solar para el calentamiento de agua.</p><p>Es una opción recomendada para viviendas familiares, negocios pequeños y espacios con consumo medio de agua caliente.</p><ul><li>Tipo: terma solar</li><li>Tecnología: tubos al vacío</li><li>Cantidad de tubos: 18</li><li>Aplicación: agua caliente sanitaria con energía solar</li></ul><p>Novatec Energy brinda asesoría para elegir la capacidad adecuada según cantidad de usuarios, consumo diario y condiciones de instalación.</p>', 'Terma solar de 18 tubos al vacío para calentamiento de agua con energía solar, recomendado para viviendas familiares, negocios pequeños y espacios con consumo medio de agua caliente.'),
('terma-solar-de-20-tubos-al-vacio', '<h3>Características del producto</h3><p>La Terma solar de 20 tubos al vacío aprovecha la energía solar para el calentamiento de agua.</p><p>Es una opción recomendada para viviendas familiares, negocios pequeños y espacios con consumo medio de agua caliente.</p><ul><li>Tipo: terma solar</li><li>Tecnología: tubos al vacío</li><li>Cantidad de tubos: 20</li><li>Aplicación: agua caliente sanitaria con energía solar</li></ul><p>Novatec Energy brinda asesoría para elegir la capacidad adecuada según cantidad de usuarios, consumo diario y condiciones de instalación.</p>', 'Terma solar de 20 tubos al vacío para calentamiento de agua con energía solar, recomendado para viviendas familiares, negocios pequeños y espacios con consumo medio de agua caliente.'),
('terma-solar-de-25-tubos-al-vacio', '<h3>Características del producto</h3><p>La Terma solar de 25 tubos al vacío aprovecha la energía solar para el calentamiento de agua.</p><p>Es una opción recomendada para viviendas con mayor demanda, hospedajes, negocios o instalaciones que requieren más disponibilidad de agua caliente.</p><ul><li>Tipo: terma solar</li><li>Tecnología: tubos al vacío</li><li>Cantidad de tubos: 25</li><li>Aplicación: agua caliente sanitaria con energía solar</li></ul><p>Novatec Energy brinda asesoría para elegir la capacidad adecuada según cantidad de usuarios, consumo diario y condiciones de instalación.</p>', 'Terma solar de 25 tubos al vacío para calentamiento de agua con energía solar, recomendado para viviendas con mayor demanda, hospedajes, negocios o instalaciones que requieren más disponibilidad de agua caliente.'),
('terma-solar-de-30-tubos-al-vacio', '<h3>Características del producto</h3><p>La Terma solar de 30 tubos al vacío aprovecha la energía solar para el calentamiento de agua.</p><p>Es una opción recomendada para viviendas con mayor demanda, hospedajes, negocios o instalaciones que requieren más disponibilidad de agua caliente.</p><ul><li>Tipo: terma solar</li><li>Tecnología: tubos al vacío</li><li>Cantidad de tubos: 30</li><li>Aplicación: agua caliente sanitaria con energía solar</li></ul><p>Novatec Energy brinda asesoría para elegir la capacidad adecuada según cantidad de usuarios, consumo diario y condiciones de instalación.</p>', 'Terma solar de 30 tubos al vacío para calentamiento de agua con energía solar, recomendado para viviendas con mayor demanda, hospedajes, negocios o instalaciones que requieren más disponibilidad de agua caliente.'),
('panel-solar-5w-12v', '<h3>Características del producto</h3><p>El Panel solar 5W 12V es una alternativa práctica para aprovechar la energía solar en iluminación básica, pequeños consumos, cercos eléctricos, cámaras, carga de baterías pequeñas y aplicaciones solares puntuales.</p><p>Este panel solar requiere dimensionamiento técnico junto con los demás componentes del sistema solar.</p><ul><li>Potencia: 5W</li><li>Voltaje nominal: 12V</li><li>Categoría: Paneles solares</li><li>Uso recomendado: iluminación básica, pequeños consumos, cercos eléctricos, cámaras, carga de baterías pequeñas y aplicaciones solares puntuales</li></ul><p>En Novatec Energy brindamos asesoría para elegir el panel adecuado según consumo, autonomía requerida y tipo de sistema solar.</p>', 'Panel solar 5W 12V para iluminación básica, pequeños consumos, cercos eléctricos, cámaras, carga de baterías pequeñas y aplicaciones solares puntuales, ideal para proyectos de energía solar y carga de baterías.'),
('panel-solar-10w-12v', '<h3>Características del producto</h3><p>El Panel solar 10W 12V es una alternativa práctica para aprovechar la energía solar en iluminación básica, pequeños consumos, cercos eléctricos, cámaras, carga de baterías pequeñas y aplicaciones solares puntuales.</p><p>Este panel solar requiere dimensionamiento técnico junto con los demás componentes del sistema solar.</p><ul><li>Potencia: 10W</li><li>Voltaje nominal: 12V</li><li>Categoría: Paneles solares</li><li>Uso recomendado: iluminación básica, pequeños consumos, cercos eléctricos, cámaras, carga de baterías pequeñas y aplicaciones solares puntuales</li></ul><p>En Novatec Energy brindamos asesoría para elegir el panel adecuado según consumo, autonomía requerida y tipo de sistema solar.</p>', 'Panel solar 10W 12V para iluminación básica, pequeños consumos, cercos eléctricos, cámaras, carga de baterías pequeñas y aplicaciones solares puntuales, ideal para proyectos de energía solar y carga de baterías.'),
('panel-solar-20w-12v', '<h3>Características del producto</h3><p>El Panel solar 20W 12V es una alternativa práctica para aprovechar la energía solar en iluminación básica, pequeños consumos, cercos eléctricos, cámaras, carga de baterías pequeñas y aplicaciones solares puntuales.</p><p>Este panel solar requiere dimensionamiento técnico junto con los demás componentes del sistema solar.</p><ul><li>Potencia: 20W</li><li>Voltaje nominal: 12V</li><li>Categoría: Paneles solares</li><li>Uso recomendado: iluminación básica, pequeños consumos, cercos eléctricos, cámaras, carga de baterías pequeñas y aplicaciones solares puntuales</li></ul><p>En Novatec Energy brindamos asesoría para elegir el panel adecuado según consumo, autonomía requerida y tipo de sistema solar.</p>', 'Panel solar 20W 12V para iluminación básica, pequeños consumos, cercos eléctricos, cámaras, carga de baterías pequeñas y aplicaciones solares puntuales, ideal para proyectos de energía solar y carga de baterías.'),
