-- Importación completa del catálogo SEO de Novatec Energy.
-- Ejecutar en la base de datos de producción indicada antes de iniciar la transacción.
USE `u543705487_novatec`;
SET NAMES utf8mb4;
START TRANSACTION;

-- Reinicio exclusivo del catálogo. No elimina archivos físicos ni datos administrativos.
DELETE FROM `products_files`;
DELETE FROM `productos`;
DELETE FROM `subcategory`;
DELETE FROM `category`;


SELECT c.id, 'Termas solares de tubos al vacío', 'termas-de-tubos-al-vacio' FROM category c WHERE c.slug = 'termas-solares'
UNION ALL
SELECT c.id, 'Paneles solares de 12V', 'paneles-solares-12v' FROM category c WHERE c.slug = 'paneles-solares'
UNION ALL
SELECT c.id, 'Paneles solares de 24V', 'paneles-solares-24v' FROM category c WHERE c.slug = 'paneles-solares'
UNION ALL
SELECT c.id, 'Inversores solares de 12V', 'inversores-12v' FROM category c WHERE c.slug = 'inversores-solares'
UNION ALL
SELECT c.id, 'Inversores solares de 24V', 'inversores-24v' FROM category c WHERE c.slug = 'inversores-solares'
UNION ALL
SELECT c.id, 'Inversores solares de 48V', 'inversores-48v' FROM category c WHERE c.slug = 'inversores-solares'
UNION ALL
SELECT c.id, 'Inversores solares de alta potencia', 'inversores-de-alta-potencia' FROM category c WHERE c.slug = 'inversores-solares'
UNION ALL
SELECT c.id, 'Controladores de carga solar 12V/24V', 'controladores-12v-24v' FROM category c WHERE c.slug = 'controladores-solares'
UNION ALL
SELECT c.id, 'Controladores de carga solar 24V/48V', 'controladores-24v-48v' FROM category c WHERE c.slug = 'controladores-solares'
UNION ALL
SELECT c.id, 'Baterías AGM de 12V', 'baterias-agm-12v' FROM category c WHERE c.slug = 'baterias-solares'
UNION ALL
SELECT c.id, 'Baterías GEL de 12V', 'baterias-gel-12v' FROM category c WHERE c.slug = 'baterias-solares'
UNION ALL
SELECT c.id, 'Baterías de litio de 12V', 'baterias-de-litio-12v' FROM category c WHERE c.slug = 'baterias-solares'
UNION ALL
SELECT c.id, 'Baterías de litio de 24V', 'baterias-de-litio-24v' FROM category c WHERE c.slug = 'baterias-solares'
UNION ALL
SELECT c.id, 'Baterías de litio de 48V', 'baterias-de-litio-48v' FROM category c WHERE c.slug = 'baterias-solares';

CREATE TEMPORARY TABLE `_import_productos_novatec` (
  `category_slug` varchar(120) NOT NULL,
  `subcategory_slug` varchar(120) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `slug` varchar(180) NOT NULL,
  `precio_normal` decimal(10,2) NOT NULL
) ENGINE=MEMORY DEFAULT CHARSET=utf8mb4;


SELECT
  t.`nombre`,
  t.`slug`,
  CONCAT(
    '<p>', t.`nombre`, '.</p><h3>Datos del producto</h3>',
    '<p>',
    CASE
      WHEN t.`category_slug` = 'termas-solares' THEN 'Terma solar de tubos al vacío para calentamiento de agua. La cantidad de tubos se indica en el nombre del modelo.'
      WHEN t.`category_slug` = 'paneles-solares' THEN 'Panel solar identificado por la potencia y el voltaje nominales indicados en el nombre del modelo.'
      WHEN t.`category_slug` = 'inversores-solares' THEN 'Inversor solar identificado por la potencia, el voltaje y, cuando figura en el nombre, la corriente y el controlador MPPT.'
      WHEN t.`category_slug` = 'controladores-solares' THEN 'Controlador de carga solar identificado por la corriente y el rango de voltaje indicados en el nombre del modelo.'
      ELSE 'Batería para sistemas solares identificada por su marca, tipo, voltaje y capacidad nominales.'
    END,
    '</p><ul><li>Categoría: ', c.`category`, '</li><li>Subcategoría: ', s.`subcategory`, '</li></ul>',
    '<p>Solicita asesoría técnica y cotización por WhatsApp a Novatec Energy en Puno.</p>'
  ),
  CONCAT(t.`nombre`, '. Solicita cotización y asesoría técnica en Puno por WhatsApp.'),
  t.`precio_normal`,
  0.00,
  0,
  NULL,
  c.`id`,
  s.`id`
FROM `_import_productos_novatec` t
INNER JOIN `category` c ON c.`slug` = t.`category_slug`
INNER JOIN `subcategory` s ON s.`slug` = t.`subcategory_slug` AND s.`id_category` = c.`id`;

CREATE TEMPORARY TABLE `_import_descripciones_seo_novatec` (
  `slug` varchar(180) NOT NULL,
  `descripcion` text NOT NULL,
  `breve_descripcion` varchar(400) NOT NULL,
  PRIMARY KEY (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


UPDATE `productos` p
INNER JOIN `_import_descripciones_seo_novatec` t ON t.`slug` = p.`slug`
SET
  p.`descripcion` = t.`descripcion`,
  p.`breve_descripcion` = t.`breve_descripcion`;

DROP TEMPORARY TABLE `_import_descripciones_seo_novatec`;

DROP TEMPORARY TABLE `_import_productos_novatec`;

COMMIT;

-- Verificación posterior: deben devolver 5 categorías, 14 subcategorías y 57 productos.
SELECT
  (SELECT COUNT(*) FROM `category`) AS total_categorias,
  (SELECT COUNT(*) FROM `subcategory`) AS total_subcategorias,
  (SELECT COUNT(*) FROM `productos`) AS total_productos;

SELECT
  c.`category`,
  s.`subcategory`,
  COUNT(p.`id`) AS total_productos
FROM `category` c
INNER JOIN `subcategory` s ON s.`id_category` = c.`id`
LEFT JOIN `productos` p ON p.`id_categoria` = c.`id` AND p.`id_subcategory` = s.`id`
GROUP BY c.`id`, s.`id`
ORDER BY c.`category`, s.`subcategory`;
